class Car(val doc: MutableMap<String, Any?>) {
    var model: String by doc      // reads and writes doc["model"], casting on the way out
    var price: Int by doc
}
val car = Car(mutableMapOf("model" to "300SL", "price" to 100))
car.price = 120                   // view and store remain the same map
println(car.doc)                  // {model=300SL, price=120}

